SELECT 
FROM menu


    parent_menu_id = #{criteria.parentMenuId}


    AND
    use_yn = #{criteria.useYn}


ORDER BY parent_menu_id NULLS FIRST, display_order, menu_id

SELECT 
FROM menu
WHERE menu_name = #{menuName}
  AND screen_id = #{screenId}

mapper.insert:
INSERT INTO menu (
  menu_id, menu_name, parent_menu_id, display_order, screen_id, url, icon, business_category, description, use_yn
) VALUES (
  #{menuId}, #{request.menuName}, NULLIF(#{request.parentMenuId}, ''), #{request.displayOrder}, #{request.screenId},
  #{request.url}, NULLIF(#{request.icon}, ''), NULLIF(#{request.businessCategory}, ''), NULLIF(#{request.description}, ''), #{useYn}
)

INSERT INTO change_history (
  change_history_id, entity_name, entity_id, before_value, after_value, actor_user_id, changed_at, reason, status
) VALUES (
  #{changeHistoryId}, #{entityName}, #{entityId}, CAST(#{beforeValue} AS jsonb), CAST(#{afterValue} AS jsonb),
  #{actorUserId}, current_timestamp, #{reason}, 'RECORDED'
)
